<?php require 'config/config.php'; if(!empty($_SESSION['user'])) redirect('index.php'); $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=db()->prepare("SELECT * FROM users WHERE username=? AND status='Active'");$s->execute([trim($_POST['username'])]);$u=$s->fetch();if($u && password_verify($_POST['password'],$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=$u;redirect('index.php');}$err='Invalid username or password.';} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login - AIA PHARMACY</title><link rel="stylesheet" href="<?=BASE_URL?>assets/style.css"></head><body class="login"><div class="login-box"><h1>AIA PHARMACY</h1><p>Management System Login</p><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><p><label>Username</label><input name="username" required autofocus></p><p><label>Password</label><input type="password" name="password" required></p><button style="width:100%">Sign In</button></form></div></body></html>
